import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import './App.css';
import './components/Authentication/Auth.css';
import './components/Navbar/Navbar.css';
import LoginForm from './components/Authentication/LoginForm';
import SignupForm from './components/Authentication/SignupForm';
import Navbar from './components/Navbar/Navbar';
import Homepage from './components/home';
import 'bootstrap/dist/css/bootstrap.min.css';

function App() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem('authToken');
    const email = localStorage.getItem('userEmail');
    if (token && email) {
      setUser({ email });
    }
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('userEmail');
    setUser(null);
  };

  return (
    <div className="App">
      {/* Single Router wrapping the entire application */}
      <Router>
        <Navbar user={user} handleLogout={handleLogout} />
        <header className="App-header">
          <h1>Multi-Vendor Platform</h1>
        </header>
        <main>
          <Routes>
            {/* Redirect to login if no user is logged in */}
            <Route path="/" Component={user ? <Navigate to="/home" /> : <LoginForm setUser={setUser} />} />
            <Route path="/signup" Component={<SignupForm />} />
            <Route path="/home" element={user ? <Homepage user={user} /> : <Navigate to="/" />} />
          </Routes>
        </main>
      </Router>
    </div>
  );
}

export default App;
